28	  steps: Step[];
29	}
30	
31	export type StepResult =
32	  | { premium: number }
33	  | { payout: number; remainingCap: number };
34	
35	export interface ScenarioResult {
36	  results: StepResult[];
37	}
38	
39	const PROCESSING_FEE = 5;
40	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
41	  sword: 100,
42	  amulet: 60,
43	  staff: 80,
44	  potion: 40,
45	};
46	const FIRST_INSURANCE_RATE = 0.1;
47	
48	const withFirstInsuranceSurcharge = (basePremium: number): number =>
49	  basePremium + basePremium * FIRST_INSURANCE_RATE;
50	
51	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
52	
53	const policyBasePremium = (items: Item[]): number =>
54	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
55	
56	const quotePremium = (items: Item[]): number =>
57	  withFirstInsuranceSurcharge(policyBasePremium(items)) + PROCESSING_FEE;
58	
59	const runStep = (step: Step): StepResult => {
60	  if (step.op === "quote") return { premium: quotePremium(step.items) };
61	  throw new Error(`unsupported step: ${step.op}`);
62	};
63	
64	export const runScenario = (scenario: Scenario): ScenarioResult => ({
65	  results: scenario.steps.map(runStep),
66	});
